import icontract


@icontract.require(lambda n: n >= 0)
@icontract.ensure(lambda result: result >= 0)
@icontract.ensure(lambda n, result: result == (n * (2 * n - 1) * (2 * n + 1)) // 3)
def sumOfSquaresOfFirstNOddNumbers(n: int) -> int:
    total = 0
    k = 1
    while k <= n:
        total += (2 * k - 1) * (2 * k - 1)
        k += 1
    return total
